import importlib.util
import inspect
import json
import os
import sys

repo_root = '/testbed'
test_path = '/testbed/qa_instances_eval/python-control/optimal_solve_trajectory_call_coverage_suite/files/tests/qa/optimal_solve_trajectory_call_coverage_suite_test.py'

prefixes = (
    'control.optimal.',
    'control.nlsys.',
    'control.timeresp.',
    'control.iosys.',
    'control.statesp.',
    'control.config.',
)

target_module = 'control.optimal'
target_name = 'solve_optimal_trajectory'

depth = 0
covered = set()


def profiler(frame, event, arg):
    global depth
    if event in ('call', 'return', 'exception'):
        mod = frame.f_globals.get('__name__', '')
        co_name = frame.f_code.co_name

        is_target = (mod == target_module and co_name == target_name)

        if event == 'call':
            if depth > 0:
                fullname = f"{mod}.{co_name}"
                if co_name.find('<') == -1 and any(fullname.startswith(p) for p in prefixes):
                    fn = frame.f_code.co_filename.replace('\\\\', '/')
                    if '/control/tests/' not in fn:
                        rel = os.path.relpath(fn, repo_root).replace('\\\\', '/')
                        covered.add((rel, fullname))
            if is_target:
                depth += 1
                # include target itself
                fn = frame.f_code.co_filename.replace('\\\\', '/')
                if '/control/tests/' not in fn:
                    rel = os.path.relpath(fn, repo_root).replace('\\\\', '/')
                    covered.add((rel, f"{mod}.{co_name}"))
            elif depth > 0:
                fullname = f"{mod}.{co_name}"
                if co_name.find('<') == -1 and any(fullname.startswith(p) for p in prefixes):
                    fn = frame.f_code.co_filename.replace('\\\\', '/')
                    if '/control/tests/' not in fn:
                        rel = os.path.relpath(fn, repo_root).replace('\\\\', '/')
                        covered.add((rel, fullname))

        elif event in ('return', 'exception'):
            if depth > 0:
                fullname = f"{mod}.{co_name}"
                if co_name.find('<') == -1 and any(fullname.startswith(p) for p in prefixes):
                    fn = frame.f_code.co_filename.replace('\\\\', '/')
                    if '/control/tests/' not in fn:
                        rel = os.path.relpath(fn, repo_root).replace('\\\\', '/')
                        covered.add((rel, fullname))
            if is_target and depth > 0:
                depth -= 1

    return profiler


spec = importlib.util.spec_from_file_location('qa_test_module', test_path)
mod = importlib.util.module_from_spec(spec)
spec.loader.exec_module(mod)

classes = [obj for _, obj in inspect.getmembers(mod, inspect.isclass) if obj.__module__ == 'qa_test_module']
classes = [c for c in classes if c.__name__.startswith('Test')]

sys.setprofile(profiler)
try:
    total = 0
    for cls in classes:
        inst = cls()
        for name, meth in inspect.getmembers(inst, predicate=callable):
            if name.startswith('test_'):
                total += 1
                meth()
finally:
    sys.setprofile(None)

print(f"Executed {total} tests")
print(f"Covered {len(covered)} functions")
for file, func in sorted(covered):
    print(file + ' :: ' + func)

# Also emit JSON to temporary location for easy copy
out = {
    'covered_functions': [
        {'file': file, 'func': func}
        for file, func in sorted(covered)
    ]
}
with open('/tmp/qa_covered.json', 'w') as f:
    json.dump(out, f, indent=2)
print('Wrote /tmp/qa_covered.json')
